#pragma once

#include "integration/exe_check.h"

#include <cstdint>

namespace mothervr::hook {

// Named slots in the original's 127-entry AI.exe address table. The value is
// the table index, i.e. (original global - DAT_10066bc8) / 4. Only the slots
// the reconstruction uses are named; the full per-build tables live in
// ai_address_tables.inc (generated by scripts/gen_ai_addresses.py).
enum class AiAddr : std::uint8_t {
    FollowOnActivatePatch    = 0x02, // DAT_10066bd0  FollowBehavior::OnActivate; +8: `mov [esi+0x264],al`
    FollowLookState          = 0x03, // DAT_10066bd4  `mov cl,[esp+0xf]` setting FollowBehavior +0x261
    CameraNoiseCall          = 0x04, // DAT_10066bd8  `mov ecx,esi; call` camera sway/breathing
    HeadClipCompare          = 0x05, // DAT_10066bdc  `comiss xmm0,[1e-5]`; disp32 at +3
    CameraCorrectionBranch   = 0x06, // DAT_10066be0  `jbe` into the VR camera correction
    FireStr2                 = 0x0A, // DAT_10066bf0  script call (name, str, str)
    FireBool                 = 0x0B, // DAT_10066bf4  script call (name, bool)
    FireInt                  = 0x0C, // DAT_10066bf8  script call (name, int)
    FireFloat                = 0x0D, // DAT_10066bfc  script call (name, float)
    MenuOpen                 = 0x12, // DAT_10066c10  stock method behind MenuVtable slot 0
    OriginalCmdHandler       = 0x16, // DAT_10066c20  stock console command handler
    BootupMoviePush          = 0x17, // DAT_10066c24  `push "ShowBootup"`; operand at +1
    UiMouseWidthLoad         = 0x18, // DAT_10066c28  `movss xmm2,[W]`; disp low byte at +4
    UiMouseHeightLoad        = 0x19, // DAT_10066c2c  same for H
    UiInputModeBranch        = 0x1A, // DAT_10066c30  `je` in the menu input-mode handler
    CutsceneVisibilityStart  = 0x1F, // DAT_10066c44  message name hashes (globals)
    CutsceneVisibilityFinish = 0x20, // DAT_10066c48
    LevelFadeStart           = 0x21, // DAT_10066c4c
    LevelFadeFinish          = 0x22, // DAT_10066c50
    SsaoSettingBranch        = 0x25, // DAT_10066c5c  `jne` in the SSAO setting handler
    KeyboardKeyDown          = 0x30, // DAT_10066c88  keyboard.KeyDown(scancode)
    KeyboardAnyKey           = 0x31, // DAT_10066c8c  keyboard.AnyKey()
    GraphicsSetOption        = 0x34, // DAT_10066c98  settings.SetOption(int, const char*)
    StereoManagerAlloc       = 0x35, // DAT_10066c9c  `push 0xb0` before new(stereo manager)
    HeadPoseCallA            = 0x36, // DAT_10066ca0  `mov eax,[eax+0x2c]`: device slot 11
    HeadPoseCallB            = 0x37, // DAT_10066ca4  same
    GameDeviceEyeTransform   = 0x44, // DAT_10066cd8  game stereo device slot 12
    GameDeviceFovAspect      = 0x45, // DAT_10066cdc  slot 13
    GameDeviceEyeScaleOffset = 0x46, // DAT_10066ce0  slot 14
    GamePushMode             = 0x4F, // DAT_10066d04  Stereo::PushMode(int)
    GamePopMode              = 0x50, // DAT_10066d08  Stereo::PopMode()
    RendererDevice           = 0x51, // DAT_10066d0c  (Renderer*) -> ID3D11Device*
    RendererSwapChain        = 0x52, // DAT_10066d10  (Renderer*) -> IDXGISwapChain*
    RendererContext          = 0x53, // DAT_10066d14  (Renderer*) -> ID3D11DeviceContext*
    RendererRtTexture        = 0x54, // DAT_10066d18  (Renderer*, index) -> ID3D11Texture2D*
    RendererRtSrv            = 0x55, // DAT_10066d1c  (Renderer*, index) -> SRV*
    AudioReopenOutput        = 0x57, // DAT_10066d24  the audio engine reopens its output device
    MouseActive              = 0x58, // DAT_10066d28  mouse.Active()
    FollowVtable             = 0x59, // DAT_10066d2c  FollowBehavior vtable (slots 0, 1)
    UiEntityMessageSlot      = 0x5A, // DAT_10066d30  UI entity vtable slot 2 (OnMessage)
    UiPakPathPtr             = 0x5B, // DAT_10066d34  pointer to "data\ui.pak"
    DisplayResetFlag         = 0x5F, // DAT_10066d44  byte: the game rebuilds its render targets
    GraphicsSettings         = 0x60, // DAT_10066d48  the settings object (in .data)
    InputManagerPtr          = 0x61, // DAT_10066d4c  global holding the input manager
    PovManagerPtr            = 0x62, // DAT_10066d50  global holding the POV manager
    ExitRequest              = 0x64, // DAT_10066d58  byte: the game quits (set after mvr_vrruntime and on the runtime's quit request)
    RendererPtr              = 0x65, // DAT_10066d5c  global holding the Renderer*
    CreateDeviceCall         = 0x67, // DAT_10066d64  call Stereo::Init(int)
    StereoUpdateCall         = 0x68, // DAT_10066d68  call Stereo::Update(float)
    VirtualScreenCall        = 0x69, // DAT_10066d6c  call BuildUiQuad in SetMode(1)
    HudPanelCall             = 0x6A, // DAT_10066d70  call BuildUiQuad in DrawOverlay
    HmdResolutionCall        = 0x6B, // DAT_10066d74  call Stereo::GetDisplaySize(int*, int*)
    RenderTargetSizeCall     = 0x6C, // DAT_10066d78  call Stereo::GetRenderTargetSize(int*, int*)
    PushModeCallA            = 0x6D, // DAT_10066d7c  call Stereo::PushMode
    PushModeCallB            = 0x6E, // DAT_10066d80
    PushModeCallC            = 0x6F, // DAT_10066d84
    PopModeCallA             = 0x70, // DAT_10066d88  call Stereo::PopMode
    PopModeCallB             = 0x71, // DAT_10066d8c
    PopModeCallC             = 0x72, // DAT_10066d90
    ResumeGamePopMode        = 0x73, // DAT_10066d94  11 bytes: PopMode in "Resume_game"
    PauseMenuPushMode        = 0x74, // DAT_10066d98  13 bytes: PushMode(1) in "Pause"
    MenuVtable               = 0x75, // DAT_10066d9c  front-end menu vtable
    PauseMenuVtable          = 0x76, // DAT_10066da0  pause menu vtable
    LoadingScreenVtable      = 0x77, // DAT_10066da4  loading screen vtable
    AttractScreenVtable      = 0x78, // DAT_10066da8  attract/title video screen vtable
    LoaderSleepPush          = 0x79, // DAT_10066dac  `push ecx` before SleepEx(33 - elapsed)
    PadVtable                = 0x7A, // DAT_10066db0  XInput pad vtable (+4), see input/gamepad.h
    PadConnectedSet          = 0x7B, // DAT_10066db4  `setne cl`: pad connected flag
    LeftStickPromptCall      = 0x7C, // DAT_10066db8  call IsMoveOnLeftStick (+0, +0xEC)
    CmdDispatchSlot          = 0x7E, // DAT_10066dc0  pointer to the console command handler
};

// Select the table for `version` and rebase it onto `ai_base`.
// From: FUN_10001760 @ 0x10001760 (rebase) + FUN_10001840 @ 0x10001840
// (Patched_2020 table); the Original_2015 table is the static initializer
// of DAT_10066bc8.
void init_ai_addresses(std::uint8_t* ai_base, integration::AIVersion version) noexcept;

// Absolute address of `slot` in the running AI.exe. Only valid after
// init_ai_addresses().
std::uint8_t* ai_address(AiAddr slot) noexcept;

// True if every address in the selected table lies inside AI.exe's image
// of `image_size` bytes, so the preflight can read them.
bool ai_addresses_within(std::uint32_t image_size) noexcept;

} // namespace mothervr::hook
